  bool OnProcessMessageReceived(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, CefProcessId source_process, CefRefPtr<CefProcessMessage> message) override {
    zend_function* cl_fn = hooks_[18];
    if (!cl_fn) {
      return CefClient::OnProcessMessageReceived(browser, frame, source_process, message);
    }
    bool cl_result = bool();
    cl::run_on_php_thread([&]() {
      zval cl_args[4];
      cl_wrap_CefBrowser(&cl_args[0], browser.get());
      cl_wrap_CefFrame(&cl_args[1], frame.get());
      ZVAL_LONG(&cl_args[2], static_cast<zend_long>(source_process));
      cl_wrap_CefProcessMessage(&cl_args[3], message.get());
      zval cl_rv;
      ZVAL_UNDEF(&cl_rv);
      bool cl_ok = cl::call_method(object(), cl_fn, 4, cl_args, &cl_rv);
      if (cl_ok) {
        if (zval* cl_r = cl::result_at(&cl_rv, 1, 0)) {
          cl_result = zend_is_true(cl_r);
        }
      }
      if (Z_TYPE(cl_rv) != IS_UNDEF) zval_ptr_dtor(&cl_rv);
      for (int cl_i = 0; cl_i < 4; ++cl_i) {
        cl::invalidate_buffers(&cl_args[cl_i]);
        zval_ptr_dtor(&cl_args[cl_i]);
      }
    });
    return cl_result;
  }

